def cmd_group(args, opts):
    _need_min_args(args, 3, "group FILE BY AGGREGATE...")
    specs = args[2:]
    if len(set(specs)) != len(specs):
        raise UsageError("group: aggregate given twice in %s" % " ".join(specs))
    aggregates = [_parse_aggregate(spec) for spec in specs]
    table = load(args[0])
    by_at = table.index(args[1])
    positions = [None if column is None else table.index(column) for _, column in aggregates]
    names = [spec.replace(":", "_") for spec in specs]
    columns = [args[1]] + names
    for at, name in enumerate(columns):
        if name in columns[:at]:
            raise TabulaError("%s: the result would have the column %r twice" % (table.source, name))
    groups = {}
    with localcontext(EXACT):
        for number, row in enumerate(table.rows, 1):
            members = groups.setdefault(row[by_at], [0] + [[] for _ in aggregates])
            members[0] += 1
            for k, ((_, column), at) in enumerate(zip(aggregates, positions), 1):
                if at is not None:
                    members[k].append(_need_cell_number(table, number, column, row[at]))
        rows = [[key] + [_aggregate_value(kind, members[k], members[0]) for k, (kind, _) in enumerate(aggregates, 1)]
                for key, members in groups.items()]
    return Table(columns, rows, table.source)


def cmd_join(args, opts):
    _need_args(args, 3, "join LEFT RIGHT KEY")
    left, right = load(args[0]), load(args[1])
    left_at, right_at = left.index(args[2]), right.index(args[2])
    extra_at = [at for at in range(len(right.columns)) if at != right_at]
    extras = [right.columns[at] + "_right" if right.columns[at] in left.columns else right.columns[at] for at in extra_at]
    columns = left.columns + extras
    for at, name in enumerate(columns):
        if name in columns[:at]:
            raise TabulaError("%s: the result would have the column %r twice" % (left.source, name))
    matches = {}
    for row in right.rows:
        matches.setdefault(row[right_at], []).append([row[at] for at in extra_at])
    blank = [[""] * len(extra_at)] if opts["kind"] == "left" else []
    rows = [row + extra for row in left.rows for extra in matches.get(row[left_at], blank)]
    return Table(columns, rows, left.source)


